:root{
  --bg:#0b1220; --panel:#101b30; --panel2:#0d1626; --line:#1f2f4d; --line2:#2a3d63;
  --text:#e2e8f0; --muted:#94a3b8; --dim:#64748b;
  --teal:#2dd4bf; --teal-dim:#0f766e; --amber:#f59e0b; --green:#4ade80; --red:#f87171;
  --radius:12px;
}
*{box-sizing:border-box}
html{color-scheme:dark}
body{margin:0;background:var(--bg);color:var(--text);
  font:15px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif}
h1{font-size:26px;margin:0;letter-spacing:.2px}
h2{font-size:19px;margin:26px 0 8px}
h3{font-size:15px;margin:24px 0 8px;color:var(--teal)}
a{color:var(--teal)}
.top{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap;
  padding:22px 28px 16px;border-bottom:1px solid var(--line);
  background:radial-gradient(900px 220px at 15% -40%,rgba(45,212,191,.16),transparent 60%),var(--panel2)}
.brand{display:flex;gap:14px;align-items:flex-start}
.sub{margin:4px 0 0;color:var(--muted);max-width:560px}
.meta{color:var(--muted);font-size:13px;text-align:right;max-width:340px;line-height:1.7}
.meta b{color:var(--text)}
.pulse{width:34px;height:34px;border:2px solid var(--teal);border-radius:50%;flex:none;margin-top:4px;position:relative}
.pulse span{position:absolute;inset:8px;border-radius:50%;background:var(--teal);animation:ping 2.4s ease-out infinite}
@keyframes ping{0%{transform:scale(.4);opacity:1}80%{transform:scale(1.5);opacity:0}100%{opacity:0}}
.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;padding:18px 28px 4px}
.stat{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:12px 14px}
.stat .k{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.6px}
.stat .v{font-size:22px;font-weight:700;margin-top:2px;font-variant-numeric:tabular-nums}
.stat .v small{font-size:13px;color:var(--muted);font-weight:400}
.stat .d{font-size:12px;color:var(--dim);margin-top:2px}
.tabs{display:flex;gap:8px;padding:14px 28px 0}
.tabs button{background:var(--panel);color:var(--muted);border:1px solid var(--line);
  border-radius:9px 9px 0 0;border-bottom:none;padding:9px 18px;font:inherit;cursor:pointer}
.tabs button.active{background:var(--panel2);color:var(--teal);font-weight:600}
.view{padding:6px 28px 30px}
.controls{display:flex;gap:12px;flex-wrap:wrap;align-items:end;margin:14px 0 6px}
.controls label{font-size:13px;color:var(--muted);display:flex;flex-direction:column;gap:4px}
.controls label.check{flex-direction:row;align-items:center;gap:6px;padding-bottom:7px;color:var(--text)}
input[type=search],select{background:var(--panel);color:var(--text);border:1px solid var(--line2);
  border-radius:8px;padding:8px 10px;font:inherit}
input[type=search]{width:220px}
select{max-width:210px}
.count{color:var(--muted);font-size:13px;margin:4px 0 10px}
.tablewrap{overflow-x:auto;border:1px solid var(--line);border-radius:var(--radius);background:var(--panel)}
table{border-collapse:collapse;width:100%;min-width:760px}
th,td{padding:9px 12px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}
th{font-size:12px;text-transform:uppercase;letter-spacing:.5px;color:var(--muted);background:var(--panel2)}
th[data-sort]{cursor:pointer}
th[data-sort]:hover{color:var(--teal)}
tbody tr:hover{background:#14223c}
tbody tr.sel{background:#12283a}
td.num,th.num{text-align:right;font-variant-numeric:tabular-nums}
td .nm{font-weight:600}
td .sl{color:var(--dim);font-size:12px}
.badge{display:inline-block;font-size:11px;font-weight:600;color:#042f2e;background:var(--teal);
  border-radius:20px;padding:1px 8px;margin-left:6px;vertical-align:1px}
.pill{display:inline-block;font-size:12px;color:var(--muted);border:1px solid var(--line2);
  border-radius:20px;padding:1px 8px;margin:1px 2px 1px 0}
.up{color:var(--green)} .down{color:var(--red)} .flat{color:var(--muted)}
.lede{color:var(--muted);max-width:860px;margin:6px 0 14px}
.formula{background:var(--panel);border:1px solid var(--line);border-left:3px solid var(--teal);
  border-radius:8px;padding:12px 14px;overflow-x:auto;margin:10px 0}
.formula code{font-size:13px;color:var(--text);white-space:nowrap}
.detail{margin-top:16px;background:var(--panel);border:1px solid var(--line2);border-radius:var(--radius);padding:18px 20px}
.detail h2{margin:0 0 2px;font-size:20px}
.detail .dsub{color:var(--muted);margin:0 0 14px}
.kv{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:12px 0}
.kv>div{background:var(--panel2);border:1px solid var(--line);border-radius:9px;padding:9px 11px}
.kv .k{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.5px}
.kv .v{font-size:17px;font-weight:700;font-variant-numeric:tabular-nums}
.kv .d{font-size:12px;color:var(--dim)}
.steps{margin:10px 0 0;padding:0;list-style:none;counter-reset:s}
.steps li{counter-increment:s;position:relative;padding:10px 0 10px 44px;border-top:1px solid var(--line)}
.steps li::before{content:counter(s);position:absolute;left:0;top:10px;width:28px;height:28px;
  border-radius:50%;background:var(--teal-dim);color:#fff;text-align:center;line-height:28px;font-weight:700;font-size:13px}
.steps .ct{color:var(--muted);font-size:13px}
.close{float:right;background:none;border:1px solid var(--line2);color:var(--muted);
  border-radius:8px;padding:5px 12px;font:inherit;cursor:pointer}
.close:hover{color:var(--text);border-color:var(--teal)}
.sandbox{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:14px;
  background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:16px}
.sandbox label{font-size:13px;color:var(--muted);display:flex;flex-direction:column;gap:6px}
.sandbox output{color:var(--teal);font-weight:600}
.sandbox input[type=range]{width:100%;accent-color:var(--teal)}
.sandbox button{grid-column:1/-1;justify-self:start;background:var(--teal-dim);color:#fff;border:none;
  border-radius:8px;padding:9px 16px;font:inherit;cursor:pointer}
.notes{color:var(--muted);max-width:860px;padding-left:20px}
.notes li{margin:6px 0}
.notes b{color:var(--text)}
footer{border-top:1px solid var(--line);padding:18px 28px 26px;color:var(--dim);font-size:13px}
footer p{margin:4px 0;max-width:900px}
@media (max-width:720px){.top,.stats,.tabs,.view{padding-left:14px;padding-right:14px}.meta{text-align:left}}
```

